    function run(address payable possibleOwner, uint sendAmount, address cmdTarget, bytes calldata cmdData) public payable {
        require(address(this).balance >= sendAmount);

        // Read observable before-values
        address beforeOwner = c.Owner();
        uint beforeBalance = address(c).balance;

        // Try calling withdraw and Command from this contract; capture revert flags
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool commandReverted;
        try c.Command{value: sendAmount}(cmdTarget, cmdData) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        // After calls, read owner and balance
        address afterOwner = c.Owner();
        uint afterBalance = address(c).balance;

        // General rule asserted for all inputs:
        // 1) c.Owner() never changes as a result of these calls (only set at construction), and
        // 2) If withdraw succeeded (did not revert) then Owner must have been the caller (but here caller is this contract), and contract balance after is either zero or unchanged depending on whether withdraw reverted; equivalently, since this contract is not the original Owner, withdraw must have reverted. Also, Command can only succeed if caller is Owner; since caller is this contract and not equal to Owner, Command must revert. We express these as: owner unchanged, and if caller != owner then both withdraw and Command reverted; if caller==owner then withdraw did not revert and afterBalance==0 (all funds transferred out).

        bool callerIsOwner = (address(this) == beforeOwner);

