        assert(
            // owner is invariant
            afterOwner == beforeOwner
            && (
                // if this test contract is not the owner, both calls must revert
                (!callerIsOwner && withdrawReverted && commandReverted)
                ||
                // if this test contract is the owner, withdraw must not revert and should drain balance, and Command may or may not revert but withdraw will make balance zero
                (callerIsOwner && !withdrawReverted && afterBalance == 0)
            )
        );
    }

    // allow receiving ether for tests
    receive() external payable {}
}

